const data = $input.first().json;
let event = data.body ?? data.message ?? data.payload ?? data;
if (typeof event === 'string') {
  try { event = JSON.parse(event); }
  catch (error) { return [{json:{send:false,reason:'Mensaje JSON no válido',error:error.message}}]; }
}
if (event && event.type === 'Buffer' && Array.isArray(event.data)) {
  try { event = JSON.parse(Buffer.from(event.data).toString('utf8')); }
  catch (error) { return [{json:{send:false,reason:'No se pudo interpretar el Buffer MQTT'}}]; }
}
if (!event || typeof event !== 'object') {
  return [{json:{send:false,reason:'Estructura de evento no válida'}}];
}
const capacity = Number(event.capacity);
const occupancy = Number(event.occupancy);
const validation = String(event.validation || 'ACEPTADO');
const eventId = String(event.eventId || 'SIN-ID');
if (!Number.isInteger(capacity) || capacity <= 0 || !Number.isInteger(occupancy) || occupancy < 0 || occupancy > capacity) {
  return [{json:{send:false,reason:'Datos de aforo invalidos',eventId,receivedKeys:Object.keys(event)}}];
}
const store = $getWorkflowStaticData('global');
const level = occupancy >= capacity ? 'MAXIMO' : occupancy * 100 >= capacity * 80 ? 'ADVERTENCIA' : 'NORMAL';
const previous = store.lastLevel || 'NORMAL';
const invalid = validation === 'REVISAR_DATOS';
let message = '';
if (invalid) {
  message = `⚠️ Smart-Tourism: evento para revisión (${eventId}). Motivo: ${event.reason || 'NO_ESPECIFICADO'}. Aforo: ${occupancy}/${capacity}.`;
} else if (level !== previous) {
  if (level === 'MAXIMO') message = `🚨 Smart-Tourism: CAPACIDAD MÁXIMA (${occupancy}/${capacity}). Restringir nuevos ingresos.`;
  else if (level === 'ADVERTENCIA') message = `⚠️ Smart-Tourism: aforo al ${Math.round(occupancy * 100 / capacity)}% (${occupancy}/${capacity}).`;
  else message = `✅ Smart-Tourism: aforo normalizado (${occupancy}/${capacity}).`;
}
if (store.lastEventId === eventId) message = '';
store.lastEventId = eventId;
if (!invalid) store.lastLevel = level;
return [{json:{send:Boolean(message),message,eventId,occupancy,capacity,level,previous,validation,source:data.message !== undefined ? 'MQTT' : 'HTTP'}}];
